def aggregate(calendar, flights, notes):
    return {
        "trip_dates": calendar,
        "flight_options": flights[:3],
        "relevant_notes": [n["text"] for n in notes],
    }

def normalize(result, source):
    if isinstance(result, list) and result and isinstance(result[0], str):
        return [{"text": r, "source": source} for r in result]
    return [{"text": r["text"], "source": source} for r in result]

try:
